mapper.select:
/* AppHome01Mapper.selectTodayAttd */
SELECT
      A.CHECK_IN_TIME       AS checkInTime
    , A.CHECK_OUT_TIME      AS checkOutTime
    , A.WORK_SEQ            AS workSeq
FROM TB_USER_ATTD_MGMT A
WHERE 1=1
  AND A.CMPNY_CD = #{ param.cmpnyCd }
  AND A.SITE_CD = #{ param.siteCd }
  AND A.USER_CD = #{ param.userCd }
  AND A.WORK_YMD = #{ param.todayYmd }
  AND A.DEL_YN = 'N'
ORDER BY
      (A.CHECK_OUT_TIME IS NULL) DESC
    , A.WORK_SEQ DESC
LIMIT 1

/* AppHome01Mapper.selectTodayCheckInOffsite */
SELECT
    CASE WHEN EXISTS (
        SELECT 1
        FROM TB_USER_ATTD_GPS G
        WHERE G.CMPNY_CD = #{ param.cmpnyCd }
          AND G.ATTD_ID = (
                SELECT A.ATTD_ID
                FROM TB_USER_ATTD_MGMT A
                WHERE A.CMPNY_CD = #{ param.cmpnyCd }
                  AND A.SITE_CD = #{ param.siteCd }
                  AND A.USER_CD = #{ param.userCd }
                  AND A.WORK_YMD = #{ param.todayYmd }
                  AND A.DEL_YN = 'N'
                ORDER BY
                      (A.CHECK_OUT_TIME IS NULL) DESC
                    , A.WORK_SEQ DESC
                LIMIT 1
          )
          AND G.GPS_INFO_TYPE = '01'
    ) THEN 1 ELSE 0 END AS isOffsite

/* AppHome01Mapper.countFullDayLeaveOn */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.SITE_CD       = #{siteCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE   <= #{baseYmd}
   AND U.END_DATE     >= #{baseYmd}

/* AppHome01Mapper.selectTodayAttdList */
SELECT
      A.CHECK_IN_TIME       AS checkInTime
    , A.CHECK_OUT_TIME      AS checkOutTime
    , A.WORK_SEQ            AS workSeq
FROM TB_USER_ATTD_MGMT A
WHERE 1=1
  AND A.CMPNY_CD = #{ param.cmpnyCd }
  AND A.SITE_CD = #{ param.siteCd }
  AND A.USER_CD = #{ param.userCd }
  AND A.WORK_YMD = #{ param.todayYmd }
  AND A.DEL_YN = 'N'
ORDER BY A.WORK_SEQ ASC

/* AppHome01Mapper.selectPrevDayOpenAttd */
SELECT
      A.WORK_YMD            AS workYmd
    , A.WORK_SEQ            AS workSeq
    , A.CHECK_IN_TIME       AS checkInTime
FROM TB_USER_ATTD_MGMT A
WHERE 1=1
  AND A.CMPNY_CD = #{ param.cmpnyCd }
  AND A.SITE_CD = #{ param.siteCd }
  AND A.USER_CD = #{ param.userCd }
  AND A.WORK_YMD = #{ prevYmd }
  AND A.DEL_YN = 'N'
  AND A.CHECK_IN_TIME IS NOT NULL
  AND A.CHECK_OUT_TIME IS NULL
ORDER BY A.WORK_SEQ DESC
LIMIT 1

/* AppHome01Mapper.selectAppliedLeaveSummary */
SELECT
      COUNT(*) AS typeCount
    , SUM(
          GREATEST(
              IFNULL(T.MAX_APLY_DAYS, 0) - IFNULL((
                  SELECT SUM(U.LEAVE_DAYS)
                    FROM TB_USER_LEAVE_USE U
                   WHERE U.CMPNY_CD     = T.CMPNY_CD
                     AND U.USER_CD      = #{userCd}
                     AND U.LEAVE_CD     = T.LEAVE_CD
                     AND U.LEAVE_STATUS = 'CONFIRMED'
                     AND U.DEL_YN       = 'N'
                     AND U.START_DATE   >=  #{fiscalStartYmd}
                     AND U.START_DATE   <   #{fiscalEndYmdExclusive}
              ), 0)
            , 0
          )
      ) AS totalRemainDays
  FROM TB_LEAVE_TYPE_MGMT T
 WHERE T.CMPNY_CD   = #{cmpnyCd}
   AND T.LEAVE_TYPE = '01'
   AND T.USE_YN     = 'Y'

/* AppHome01Mapper.selectPendingApprovalCount */
SELECT
    COUNT(1) AS pendingCount
FROM TB_USER_ATTD_REQ R
WHERE 1=1
  AND R.CMPNY_CD = #{ param.cmpnyCd }
  AND R.SITE_CD = #{ param.siteCd }
  AND R.USER_CD = #{ param.userCd }
  AND R.REQ_STATUS = '01'
  AND R.DEL_YN = 'N'

/* AppHome01Mapper.selectUserNodeCd */
SELECT
      U.NODE_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

/* AppHome01Mapper.countCoveringClose */


    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD     = #{cmpnyCd}
       AND C.SITE_CD      = #{siteCd}
       AND C.CLOSE_YM     = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND C.NODE_CD      = '*'


    WITH RECURSIVE anc AS (
        SELECT N.NODE_CD, N.PARENT_NODE_CD
          FROM TB_SITE_NODE N
         WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
        UNION ALL
        SELECT P.NODE_CD, P.PARENT_NODE_CD
          FROM TB_SITE_NODE P
          JOIN anc A2
            ON P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.NODE_CD = A2.PARENT_NODE_CD
    )
    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD     = #{cmpnyCd}
       AND C.SITE_CD      = #{siteCd}
       AND C.CLOSE_YM     = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND (
            C.NODE_CD = '*'
         OR C.NODE_CD = #{nodeCd}
         OR (C.INC_SUB_YN = 'Y' AND C.NODE_CD IN (SELECT NODE_CD FROM anc WHERE NODE_CD != #{nodeCd}))
       )
